WITH sales AS (SELECT ss.ss_sold_date_sk AS date_sk, cd.cd_gender, SUM(ss.ss_net_profit) AS sales_profit FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY ss.ss_sold_date_sk, cd.cd_gender), returns AS (SELECT cr.cr_returned_date_sk AS date_sk, cd.cd_gender, w.w_warehouse_name, SUM(cr.cr_net_loss) AS return_loss FROM catalog_returns cr JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cr.cr_returned_date_sk, cd.cd_gender, w.w_warehouse_name), combined AS (SELECT COALESCE(s.date_sk, r.date_sk) AS date_sk, COALESCE(s.cd_gender, r.cd_gender) AS gender, COALESCE(r.w_warehouse_name, 'UNKNOWN') AS warehouse_name, COALESCE(s.sales_profit, 0) AS sales_profit, COALESCE(r.return_loss, 0) AS return_loss FROM sales s FULL OUTER JOIN returns r ON s.date_sk = r.date_sk AND s.cd_gender = r.cd_gender) SELECT date_sk, gender, warehouse_name, sales_profit, return_loss, (sales_profit - return_loss) AS net_gain, SUM(sales_profit - return_loss) OVER (PARTITION BY gender ORDER BY date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS gender_7_day_cumulative, RANK() OVER (PARTITION BY gender ORDER BY (sales_profit - return_loss) DESC) AS daily_rank, CASE WHEN (sales_profit - return_loss) < 0 THEN 'Deficit' ELSE 'Surplus' END AS net_status FROM combined ORDER BY date_sk, gender
